def mark_event_leads_as_team(apps, schema_editor):
    """Existing events: tick "Team" for the event lead so payment reminders and the Monday summary reach someone."""
    import re
    EventContact = apps.get_model("planner", "EventContact")
    Event = apps.get_model("planner", "Event")
    for event in Event.objects.all():
        contacts = list(EventContact.objects.filter(event=event).order_by("position"))
        if not contacts:
            continue
        lead = next((c for c in contacts if re.search(r"lead|manager|producer", c.role or "", re.I)), contacts[0])
        lead.team = True
        lead.save(update_fields=["team"])


